import {
  Component,
  h,
  Prop,
  Event,
  State,
  Host,
  Element,
  type EventEmitter,
  type ComponentInterface,
  Watch,
} from '@stencil/core';
import { noop } from 'lodash-es';
import { paginationMessages } from '@fe-infra/keystone-locales';

import { dir, t } from '@src/shared/i18n';
import { Uncontrollable } from '@src/framework/decorators';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { registerPluginManager } from '@src/shared/unclassified/plugin';

import { getTotalPageCount, getPaginationItemList, getPaginationWindowSize } from './utils';

import type { DropdownItem } from '@src/components/ks-dropdown-menu-list/types';
import type { Value } from '@src/components/ks-value-field/types';
import type { DetailArgs } from '@src/shared/dom';
import type { PaginationVariant } from './types';
import { KsIconChevronLeft, KsIconChevronRight } from '@fe-infra/keystone-icons-stencil';

const PREFIX = 'pager';

/**
 * @part base - The base container of the component.
 * @part total - The total summary content.
 * @part page - A page item in the pagination list.
 * @part pageActive - The currently active page item.
 * @part pageSizeChanger - The page size changer select control.
 */
@Component({
  tag: 'ks-pagination',
  styleUrl: 'ks-pagination.scss',
  shadow: true,
})
export class KsPagination implements ComponentInterface {
  private wrapWithSlot: (slotName: string, children: unknown) => unknown = noop;
  private setDynamicRenderDeps: (items: unknown[]) => void = noop;

  @Element() el!: HTMLKsPaginationElement;

  @Uncontrollable('page', 'defaultPage', 'ksPageChange') @State() internalCurrentPage = 1;
  @Uncontrollable('pageSize', 'defaultPageSize', 'ksPageSizeChange') @State() internalPageSize = 10;

  /** Whether the pagination is disabled. When true, all controls are not interactive. */
  @Prop() disabled = false;
  /** Initial page number in uncontrolled mode. Ignored when `page` is provided. */
  @Prop() defaultPage = 1;
  /**
   * Current page number (controlled). When provided, the component becomes controlled for page state.
   * The component will emit `ksPageChange`, but internal page state won't change unless the prop updates.
   */
  @Prop() page?: number;
  /** Initial page size in uncontrolled mode. Ignored when `pageSize` is provided. */
  @Prop() defaultPageSize = 10;
  /**
   * Page size (controlled). When provided, the component becomes controlled for page size.
   * The component will emit `ksPageSizeChange`, but internal page size won't change unless the prop updates.
   */
  @Prop() pageSize?: number;
  /**
   * Candidate page sizes for the user to select. Only rendered when `showPageSizeChanger` is true.
   * Selecting a page size may clamp the current page to the last available page.
   */
  @Prop() pageSizeOptions: number[] = [10];
  /** Visual style of the pagination. Available options: `mini`, `full`, `miniSelect`. */
  @Prop() variant: PaginationVariant = 'full';
  /** Total number of records across all pages. Used with `pageSize` to compute total pages. */
  @Prop() total = 0;
  /** Whether to show the page jump input. */
  @Prop() showQuickJumper = false;
  /** Whether to show the page size changer. */
  @Prop() showPageSizeChanger = false;
  /**
   * Number of contiguous page numbers to show on each side between the ellipses in `md` mode.
   * Controls the visible window of page buttons.
   */
  @Prop() siblingCount = 2;
  /** Whether to hide the pagination when there is only one page. */
  @Prop() hideOnSinglePage = false;
  /**
   * Whether to display the total number of records.
   * When a function is provided, its return value is rendered as the total summary content.
   */
  @Prop() showTotal: boolean | ((total: number, range: number) => unknown) = false;
  /** Custom renderer for a pagination item. Called with the page number and should return display content. */
  @Prop() renderItem?: (page: number) => unknown;

  /**
   * Fired when the current page changes. Payload is the new page number.
   * Triggers on prev/next click, number button click, and dropdown selection.
   * Emitted in both controlled and uncontrolled modes.
   */
  @Event({ bubbles: false, composed: false }) ksPageChange!: EventEmitter<number>;
  /**
   * Emitted when the page size changes. Payload is the new page size.
   * If the current page becomes out of range, the component also clamps the current page.
   */
  @Event({ bubbles: false, composed: false }) ksPageSizeChange!: EventEmitter<number>;

  constructor() {
    registerPluginManager(this.el);
  }

  componentWillLoad() {
    this.handleDynamicSlotsDepsChange();
  }

  @Watch('siblingCount')
  @Watch('total')
  @Watch('internalPageSize')
  @Watch('internalCurrentPage')
  @Watch('showTotal')
  @Watch('renderItem')
  handleDynamicSlotsDepsChange() {
    this.updateDynamicSlots();
  }

  private updateDynamicSlots = () => {
    const { siblingCount, total, internalPageSize, internalCurrentPage, showTotal, renderItem } = this;

    const dynamicSlots = [];

    if (typeof renderItem === 'function') {
      const totalPageCount = getTotalPageCount(total, internalPageSize);
      const pageItems = getPaginationItemList({
        siblingCount,
        totalPageCount,
        currentPage: internalCurrentPage,
      });

      dynamicSlots.push(...pageItems.map(({ value }) => this.wrapWithSlot(`page-item-${value}`, renderItem(value))));
    }

    if (typeof showTotal === 'function') {
      dynamicSlots.push(this.wrapWithSlot('total', showTotal(total, internalCurrentPage * internalPageSize)));
    }

    this.setDynamicRenderDeps(dynamicSlots);
  };

  private handleChange = (page: number) => () => {
    this.internalCurrentPage = page;

    sendActionTracking(this.el, { eventType: 'change', subEventType: 'page', componentParams: { page } });
  };

  private handlePaginationChange = ({
    detail,
  }: CustomEvent<DetailArgs<[Value | Value[], DropdownItem | DropdownItem[]]>>) => {
    const page = Number(detail[0]);

    this.internalCurrentPage = page;

    sendActionTracking(this.el, { eventType: 'change', subEventType: 'page', componentParams: { page } });
  };

  private handlePageSizeChange = ({
    detail,
  }: CustomEvent<DetailArgs<[Value | Value[], DropdownItem | DropdownItem[]]>>) => {
    const pageSize = Number(detail[0]);
    this.internalPageSize = pageSize;

    const totalPageCount = getTotalPageCount(this.total, pageSize);
    const page = Math.min(this.internalCurrentPage, totalPageCount);
    this.internalCurrentPage = page;

    sendActionTracking(this.el, { eventType: 'change', subEventType: 'pageSize', componentParams: { page, pageSize } });
  };

  private renderPageSizeOptions() {
    const { pageSizeOptions, disabled, internalPageSize } = this;

    if (!pageSizeOptions.length) return null;

    return (
      <ks-select
        class={`${PREFIX}__select`}
        part="pageSizeChanger"
        size="sm"
        clearable={false}
        disabled={disabled}
        value={internalPageSize}
        onKsChange={this.handlePageSizeChange}
        options={pageSizeOptions.map((item) => ({
          value: item,
          label: `${item}/${t(paginationMessages.page)}`,
        }))}
        data-testid="ks-pagination-index-dx4Jv9"
      ></ks-select>
    );
  }

  private handleQuickJump = (totalPageCount: number) => (page: number) => {
    if (page < 1 || page > totalPageCount) return;

    this.handleChange(page)();
  };

  private renderQuickJumper(totalPageCount: number) {
    const { disabled, siblingCount } = this;

    if (totalPageCount <= getPaginationWindowSize(siblingCount)) return null;

    return (
      <ks-pagination-quick-jumper
        totalPageCount={totalPageCount}
        disabled={disabled}
        onJump={this.handleQuickJump(totalPageCount)}
      >
        {t(paginationMessages.go)}
      </ks-pagination-quick-jumper>
    );
  }

  private renderPaginationSelect(totalPageCount: number) {
    const { disabled, internalCurrentPage } = this;

    const items = Array.from(
      { length: totalPageCount },
      (_, j): DropdownItem => ({
        value: j + 1,
        label: `${j + 1}`,
      }),
    );

    return (
      <ks-select
        class={`${PREFIX}__select`}
        clearable={false}
        size="md"
        disabled={disabled}
        value={internalCurrentPage}
        onKsChange={this.handlePaginationChange}
        options={items}
        data-testid="ks-pagination-ks-pagination-1tGBm2"
      ></ks-select>
    );
  }

  render() {
    const {
      disabled,
      hideOnSinglePage,
      internalCurrentPage,
      internalPageSize,
      showPageSizeChanger,
      showQuickJumper,
      showTotal,
      total,
      variant,
      siblingCount,
    } = this;

    const direction = dir();

    const totalPageCount = getTotalPageCount(total, internalPageSize);

    const isPrevDisabled = internalCurrentPage <= 1 || disabled;
    const isNextDisabled = internalCurrentPage >= totalPageCount || disabled;

    if (hideOnSinglePage && totalPageCount <= 1) return null;

    return (
      <Host class="KsPagination">
        <div class={`${PREFIX} ${PREFIX}--${variant}`} part="base">
          {showTotal && (
            <span class={`${PREFIX}__total`} part="total">
              <slot name="total">{t(paginationMessages.total, { total: this.total })}</slot>
            </span>
          )}

          <ks-icon-button
            size="sm"
            variant="text"
            disabled={isPrevDisabled}
            onClick={this.handleChange(internalCurrentPage - 1)}
            data-testid="ks-pagination-index-pEQrn1"
          >
            {direction === 'ltr' ? (
              <KsIconChevronLeft
                class={{ [`${PREFIX}__button-icon`]: true, [`${PREFIX}__button-icon--disabled`]: isPrevDisabled }}
              />
            ) : (
              <KsIconChevronRight
                class={{ [`${PREFIX}__button-icon`]: true, [`${PREFIX}__button-icon--disabled`]: isPrevDisabled }}
              />
            )}
          </ks-icon-button>

          {variant === 'mini' && (
            <div part="total" class={`${PREFIX}__item ${PREFIX}__item--simple`}>
              <span>{internalCurrentPage}</span>
              <span>/</span>
              <span>{totalPageCount}</span>
            </div>
          )}
          {variant === 'full' &&
            getPaginationItemList({
              siblingCount,
              totalPageCount,
              currentPage: internalCurrentPage,
            }).map(({ value, label }) => (
              <slot key={`page-${label}`} name={`page-item-${value}`}>
                <ks-button
                  class={{ [`${PREFIX}__item`]: true, [`${PREFIX}__item--active`]: internalCurrentPage === value }}
                  part={internalCurrentPage === value ? 'page pageActive' : 'page'}
                  size="sm"
                  variant="text"
                  disabled={this.disabled}
                  onClick={this.handleChange(value)}
                  data-testid={`ks-pagination-index-gKfSFW-${`page-${label}`}`}
                >
                  {label}
                </ks-button>
              </slot>
            ))}
          {variant === 'miniSelect' && this.renderPaginationSelect(totalPageCount)}

          <ks-icon-button
            class={`${PREFIX}__button`}
            size="sm"
            variant="text"
            disabled={isNextDisabled}
            onClick={this.handleChange(internalCurrentPage + 1)}
            data-testid="ks-pagination-index-4C8Rxx"
          >
            {direction === 'ltr' ? (
              <KsIconChevronRight
                class={{ [`${PREFIX}__button-icon`]: true, [`${PREFIX}__button-icon--disabled`]: isNextDisabled }}
              />
            ) : (
              <KsIconChevronLeft
                class={{ [`${PREFIX}__button-icon`]: true, [`${PREFIX}__button-icon--disabled`]: isNextDisabled }}
              />
            )}
          </ks-icon-button>

          {showPageSizeChanger && this.renderPageSizeOptions()}

          {showQuickJumper && this.renderQuickJumper(totalPageCount)}
        </div>
      </Host>
    );
  }
}
